import base64,gzip,hashlib,io,json,os,pathlib,tarfile
raw=base64.b64decode('',validate=True)
assert len(raw)==34133 and hashlib.sha256(raw).hexdigest()=='3788a8595ff5e5e08e7757546d176fb96385d493b26cd4b1722c610b94e76715'
with gzip.GzipFile(fileobj=io.BytesIO(raw),mode='rb') as stream:
    expanded=stream.read(512*1024+1)
assert len(expanded)<=512*1024
files={}
with tarfile.open(fileobj=io.BytesIO(expanded),mode='r:') as archive:
    for item in archive:
        name=pathlib.PurePosixPath(item.name)
        assert item.isfile() and not name.is_absolute() and '..' not in name.parts and str(name)==item.name
        assert len(name.parts)==2 and name.parts[0]=='tools-01' and len(files)<6 and item.name not in files and item.size<=128*1024
        data=archive.extractfile(item).read(128*1024+1)
        assert len(data)==item.size
        files[item.name]=data
assert len(files)==6 and sum(map(len,files.values()))==146602
manifest=files['tools-01/runner-bundle-manifest.json']
assert len(manifest)==4160 and hashlib.sha256(manifest).hexdigest()=='0e1ad9df3ae5caddc4edb47ecf1dbf1f41f3c00ad243c197c34d6c136f0597f4'
bundle=json.loads(manifest)
assert set(files)=={'tools-01/runner-bundle-manifest.json'}|{'tools-01/'+name for name in bundle['files']}
for name,pin in bundle['files'].items():
    data=files['tools-01/'+name]
    assert len(data)==pin['bytes'] and hashlib.sha256(data).hexdigest()==pin['sha256']
root=pathlib.Path('/home/qian/hepta-runtime-optimization-20261106-r35')
assert root.resolve(strict=True)==root and root.stat().st_uid==os.getuid()==1000
(root/'tools-01').mkdir(mode=0o700)
for name,data in files.items():
    path=root/name
    with path.open('xb') as stream:
        stream.write(data);stream.flush();os.fsync(stream.fileno())
    assert path.read_bytes()==data
os.execv('/usr/bin/python3',['/usr/bin/python3','-B','-u',str(root/'tools-01/install_measurement_tools.py'),'--bundle-sha256','0e1ad9df3ae5caddc4edb47ecf1dbf1f41f3c00ad243c197c34d6c136f0597f4'])
